write('capability_dependency_map.json',{'unique_records':81,'exclusive_record_partitions':dict(combos),'overlapping_membership_counts':{k:v['relevant_count'] for k,v in counts.items()},'dependencies':[{'capability':'NEUTRAL_NITRO_CHARGE_SEMANTICS','requires':['source-associated nitro identity and ownership','all additional protonation-relevant source sites accounted for','claim-specific conflicts retained','dimension-scoped evidence aggregation']},{'capability':'TAUTOMER_SOURCE_AND_CORRESPONDENCE','requires':['parent/H/suffix grammar','complete relevant mobile-site context','tautomer-specific graph correspondence','remaining charge and alias conditions']},{'capability':'CLAIM_SPECIFICITY_RECONCILIATION','requires':['per-dimension source claim scope','validated pairwise constitution/form comparison','source authority or correction when exact claims disagree']}],'note':'Apparent minimal sets describe present reason families. They do not prove these implementations suffice for eligibility.'})
priorities=[{'rank':1,'capability':'DIMENSION_SCOPED_CHARGE_EVIDENCE','category':'FOUNDATIONAL_SEMANTIC_CAPABILITY','reason':'A directly observable formal-charge trigger affects 16 neutral-nitro records, 12 with no other current reason. NSC-002 provides a working source-operation example still blocked by that trigger; repeated whole-name contracts alone do not consume this evidence.','opportunity':counts['NEUTRAL_NITRO_CHARGE_SEMANTICS'],'complexity':'Medium for evidence interface and strict closed-class consumption; high if expanded to acids, bases, zwitterions and all source sites.','risk':'High if net zero or nitro pattern is treated as complete source protonation proof.','validation':'Independent neutral/resonance versus acid/base and zwitterion adversaries; all aliases and historical charge conflicts retained.'},
{'rank':2,'capability':'DIMENSION_SPECIFIC_CLAIM_RECONCILIATION','category':'SOURCE_RECONCILIATION','reason':'26 records have alias/form differences, including 19 constitution and eight protonation reasons with overlap. Many aliases visibly denote distinct exact compounds, so ignoring aliases is unsafe and recovery is not assumed.','opportunity':counts['CLAIM_SPECIFICITY_RECONCILIATION'],'complexity':'High: source semantics and authority matter, not only parser graph comparison.','risk':'High: one unknown dimension must not make an otherwise exact contradictory claim globally broad.','validation':'Broad family, exact compatible and exact incompatible claims; per-dimension aggregation and source corrections.'},
{'rank':3,'capability':'CONTEXT_AWARE_TAUTOMER_SEMANTICS','category':'FOUNDATIONAL_SEMANTIC_CAPABILITY','reason':'51 relevant cases (41 sole current family), but six tautomer-primary names have explicit H tokens and many others use unrelated suffix families; no single small grammar is demonstrated to close them.','opportunity':counts['TAUTOMER_SOURCE_AND_CORRESPONDENCE'],'complexity':'High; multiple grammar, parent ownership and mobile-H site closure.','risk':'High if toolkit tautomer enumeration or fixed-H equality is treated as source authority.','validation':'Indicated-H/suffix composition, keto/enol, mobile-site incompleteness and symmetry without tautomer collapse.'}]
write('prioritized_capabilities.json',{'decision':'NEXT_PRIORITY_FOUNDATIONAL_SEMANTIC_CAPABILITY','ranking':priorities,'criteria':'Source specificity and false-merge risk essential; observed sole-family opportunities, reuse and independent validation feasibility determine order. No numerical scores or expected recovery rates.','checkpoint':'After first task measure semantic support, correct source-form comparisons, actual isolated eligibility and no new false EXACT. If again zero eligible improvement, review whether source adjudication or contract coverage is the real bottleneck before extending grammar.'})
write('architecture_b_reuse_assessment.json',{'existing_components':['NSC-001/002 typed claims, source spans, operations, constraints','bounded symmetry-aware graph utilities','source_form dimension dictionary and aggregate_dimensions','identity_comparator dimension outcomes','saved-evidence eligibility harness'], 'capabilities':[{'capability':p['capability'],'recommended_change':p['category'],'shared_interface':'Add a versioned dimension-evidence envelope; preserve existing NSC results and explicit unresolved dependencies.','new_rules':'Charge-site semantics, per-dimension claim scope, or context-dependent mobile-H semantics respectively.','maintenance':p['complexity'],'source_independence':True,'new_contract_required':'Only when source meaning falls outside independently validated naming rules; do not force every gap into NSC-003.'} for p in priorities],'confirmed_defects':[{'site':'identity_comparator.compare','finding':'Graph-dependent charge_views and total H differences can cause PROTONATION_DIFFERENT on constitutionally distinct inputs.','scope':'Reason attribution; global DISTINCT remains correct.'}],'not_demonstrated':['Global UNKNOWN versus SUPPORTED precedence defect','Dropped DIFFERENT in aggregate_dimensions','Validated diagnostic result being ignored accidentally: NSC diagnostic exclusion is deliberate by design.']})
spec={'objective':'Implement a versioned dimension-scoped charge/protonation evidence contract and conservative consumption in an isolated source-form assessment, initially for independently validated neutral N-attached nitro source operations.','decision':'NEXT_PRIORITY_FOUNDATIONAL_SEMANTIC_CAPABILITY','production_scope':'Default-off experimental path only. No provider/ontology/registry or default admission changes.','scientific_basis':[{'authority':'https://iupac.qmul.ac.uk/BlueBook/P7.html','meaning':'Distinguish ions, proton addition/removal and zwitterions from formal atom charge representation.'},{'authority':'https://goldbook.iupac.org/terms/view/N04158/pdf','meaning':'Nitro attaches via N; internal N+/O- is not alone a source protonation assertion.'}],
'input_classes':['Validated full source referents with source-associated nitro operations and candidate correspondence','Equivalent nitro resonance representations','Adversarial neutral nitro molecules with independent acid/base sites, ionic suffixes, salts or conflicting aliases'],
'required_evidence':['Exact original source spans and fragment ownership','Rule authority and validated source-versus-candidate graph mapping','Inventory of all charge/protonation-relevant source sites, with unresolved context explicit','All alias claim outcomes independently preserved','Candidate atom formal charges, total hydrogen, net charge and supported resonance equivalence as observations, never as source proof'],
'components':['Versioned ChargeDimensionEvidence typed model and validator','Narrow neutral-nitro structural/resonance classifier reused from NSC-002 where valid','Source-context completeness assessment','Dimension-specific consumer for source_form in isolated evaluator','Comparator reason-attribution separation for non-corresponding constitution','Saved-evidence regression and blind control runner'],
'output_contract':{'dimension':'protonation_charge','source_state':['SPECIFIED','UNSPECIFIED','CONFLICTING'],'compatibility':['SUPPORTED','DIFFERENT','UNKNOWN'],'source_claim_ids':'required','rule_ids':'required','semantic_owners':'required','candidate_correspondence':'required','sites_considered':'required','coverage_complete':'boolean with evidence','unresolved_dependencies':'required','reason_codes':'required','identity_admission':'NOT_ESTABLISHED'},
'abstention':['No inference from net neutrality or [N+](=O)[O-] alone.','Unsupported surrounding names or unmapped protonatable sites -> UNKNOWN.','Any exact conflicting source charge/constitution remains conflict.','Different constitution does not prove a particular protonation change.','One supported operation never sets every dimension supported.'],
'independent_controls':[{'case':'nitrobenzene: O=[N+]([O-])c1ccccc1 versus [O-][N+](=O)c1ccccc1','goal':'Equivalent internal nitro representation; source completeness must be independently established.'},{'case':'benzoic acid versus benzoate','goal':'Preserve true acid/conjugate-base contradiction.'},{'case':'nitroaniline and its explicitly protonated ammonium form','goal':'Nitro identity cannot settle a separate basic-site protonation.'},{'case':'nitrobenzoic acid versus nitrobenzoate','goal':'Do not suppress carboxyl protonation because nitro is net neutral.'},{'case':'glycine zwitterion versus uncharged glycine graph','goal':'Net zero does not prove identical proton locations; independently adjudicate source scope.'},{'case':'ethanol versus dimethyl ether','goal':'Constitution differs without a claimed protonation relationship.'},{'case':'unsupported mixed/salt or incomplete source context','goal':'UNKNOWN, no source specificity from candidate.'}],
'regressions':['All NSC-001 and NSC-002 frozen controls unchanged','All 81 saved-record source claims and original provider gate outcomes retained','17504, 4373, 30832, 5684, 5997, 23839, 30142 and historical dithiazole remain safely handled','Independent qualified chemical review and separate blind controls before production claim'],
'practical_value':{'potentially_affected':16,'only_current_reason':12,'dimension_supported_example':26870,'demonstrably_recoverable':0,'maximum_reason_family_opportunity':12,'qualification':'Requires source/alias adjudication and complete charge-site closure; no claimed eligibility increase.'},
'implementation_entry':'Freeze independent chemical controls and source-context closure before code; audit all 12 single-reason records individually; do not encode their CUMA IDs in runtime rules.','acceptance_checkpoint':['Validated semantic result and per-dimension provenance','Correct charge/source-form comparison','Actual isolated complete-eligibility delta on frozen evidence','No new false exact matches, conflicts suppressed or unknowns promoted','If no useful eligibility gain, reassess source-adjudication and composition dependencies before adding grammar']}
